/* Build the AML Transaction Monitoring deck.
 *
 *   cd presentation
 *   node build_deck.js            -> AML-Transaction-Monitoring.pptx
 *
 * Charts are generated by ../scripts/make_deck_figures.py into ./figures/ and
 * embedded here as base64 (no external file links, so every viewer renders them).
 * The spoken script lives in ./speaker-notes.md (read from tablet).
 */
const fs = require("fs");
const path = require("path");
const pptxgen = require("pptxgenjs");

const CORAL = "F0523C"; // Enfuce primary accent
const INK = "1A1A1A"; // near-black: titles, dark shapes, table headers
const DARK = "0F0F0F"; // darker fill for shapes on dark slides
const PALE = "F6D9D2"; // pale coral: body text on dark slides
const WHITE = "FFFFFF";
const MUTE = "6E6E6E"; // neutral grey for secondary text
const LINE = "E4E1DF"; // light warm border
const TINT = "F6F3F2"; // very light warm grey for cards
const SLATE = "8A8078"; // warm grey: storage / governance boxes in flows

const HEAD = "Arial";
const BODY = "Calibri";

const p = new pptxgen();
p.layout = "LAYOUT_WIDE"; // 13.3 x 7.5
p.theme = { headFontFace: HEAD, bodyFontFace: BODY };

const MX = 0.6;
const CW = 13.3 - MX * 2;
const TOTAL = 25;
let PAGE = 0;

/* ---------- slide factories (every slide gets a page number) ---------- */
function pageNumber(s, dark) {
  if (PAGE === 1 || PAGE === TOTAL) return; // title and closing slides have no number
  s.addText(`${PAGE} / ${TOTAL}`, {
    x: 13.3 - 1.4, y: 7.5 - 0.42, w: 1.15, h: 0.3, align: "right",
    fontFace: BODY, fontSize: 9, color: dark ? MUTE : "B3ADA9", isTextBox: true, margin: 0,
  });
}
function darkSlide() {
  PAGE += 1;
  const s = p.addSlide();
  s.background = { color: INK };
  pageNumber(s, true);
  return s;
}
function lightSlide(part, section) {
  PAGE += 1;
  const s = p.addSlide();
  s.background = { color: WHITE };
  if (part) {
    s.addShape(p.ShapeType.ellipse, { x: MX, y: 0.5, w: 0.42, h: 0.42, fill: { color: CORAL } });
    s.addText(String(part), {
      x: MX, y: 0.5, w: 0.42, h: 0.42, align: "center", valign: "middle",
      fontFace: BODY, fontSize: 13, bold: true, color: WHITE, isTextBox: true, margin: 0,
    });
    s.addText(section.toUpperCase(), {
      x: MX + 0.55, y: 0.5, w: CW - 0.55, h: 0.42, valign: "middle",
      fontFace: BODY, fontSize: 12, bold: true, color: MUTE, charSpacing: 2, isTextBox: true, margin: 0,
    });
  }
  pageNumber(s, false);
  return s;
}
function title(s, text, y = 1.05) {
  s.addText(text, {
    x: MX, y, w: CW, h: 0.9, fontFace: HEAD, fontSize: 27, bold: true, color: INK,
    isTextBox: true, margin: 0,
  });
}
function bullets(s, items, opt = {}) {
  s.addText(
    items.map((t, i) => ({
      text: t,
      options: { bullet: { code: "2022", indent: 12 }, breakLine: i < items.length - 1, paraSpaceAfter: opt.gap ?? 8 },
    })),
    {
      x: opt.x ?? MX, y: opt.y ?? 2.1, w: opt.w ?? CW, h: opt.h ?? 4.6,
      fontFace: BODY, fontSize: opt.fontSize ?? 15, color: opt.color ?? INK, valign: "top",
      isTextBox: true, margin: 0, lineSpacingMultiple: opt.ls ?? 1.05,
    }
  );
}
function card(s, x, y, w, h, fill) {
  s.addShape(p.ShapeType.roundRect, { x, y, w, h, rectRadius: 0.06, fill: { color: fill }, line: { color: LINE, width: 1 } });
}
function cardHead(s, x, y, w, t, color = INK) {
  s.addText(t, { x: x + 0.3, y: y + 0.16, w: w - 0.6, h: 0.35, fontFace: BODY, bold: true, fontSize: 13.5, color, isTextBox: true, margin: 0 });
}
function cardBody(s, x, y, w, h, t) {
  s.addText(t, { x: x + 0.3, y: y + 0.6, w: w - 0.6, h, fontFace: BODY, fontSize: 12, color: INK, isTextBox: true, margin: 0, lineSpacingMultiple: 1.05 });
}
function stat(s, x, y, w, big, label, color = INK) {
  s.addText(big, { x, y, w, h: 0.95, align: "center", fontFace: HEAD, fontSize: 40, bold: true, color, isTextBox: true, margin: 0 });
  s.addText(label, { x, y: y + 0.95, w, h: 0.6, align: "center", fontFace: BODY, fontSize: 12, color: MUTE, isTextBox: true, margin: 0 });
}
const HROW = { bold: true, color: WHITE, fill: { color: INK } };
function note(s, t) { s.addNotes(t); }

/* ---------- chart images: embedded as base64, never linked ---------- */
function pic(s, name, o) {
  const b64 = fs.readFileSync(path.join(__dirname, "figures", name)).toString("base64");
  s.addImage({ data: "image/png;base64," + b64, x: o.x, y: o.y, w: o.w, h: o.h });
}

/* ---------- flow diagram: small boxes joined by large block arrows ---------- */
function flow(s, steps, o) {
  const y = o.y, bh = o.h ?? 0.85, aw = o.aw ?? 0.6;
  const n = steps.length;
  const bw = (CW - aw * (n - 1)) / n;
  steps.forEach((st, i) => {
    const x = MX + i * (bw + aw);
    s.addShape(p.ShapeType.roundRect, {
      x, y, w: bw, h: bh, rectRadius: 0.04,
      fill: { color: st.fill ?? INK },
      line: st.line ? { color: INK, width: 1 } : { type: "none" },
    });
    s.addText(st.t, {
      x, y, w: bw, h: bh, align: "center", valign: "middle",
      fontFace: BODY, fontSize: o.fontSize ?? 9, bold: !!st.bold,
      color: st.color ?? WHITE, isTextBox: true, margin: 0,
    });
    if (i < n - 1) {
      s.addShape(p.ShapeType.rightArrow, {
        x: x + bw + 0.04, y: y + bh / 2 - 0.19, w: aw - 0.08, h: 0.38,
        fill: { color: CORAL }, line: { type: "none" },
      });
    }
  });
}

/* ---------- group bracket + label under a run of items (slide 9) ---------- */
function groupBrace(s, x, w, y, label, color) {
  const t = 0.13;
  s.addShape(p.ShapeType.line, { x, y: y + t, w, h: 0, line: { color, width: 1.75 } });
  s.addShape(p.ShapeType.line, { x, y, w: 0, h: t, line: { color, width: 1.75 } });
  s.addShape(p.ShapeType.line, { x: x + w, y, w: 0, h: t, line: { color, width: 1.75 } });
  s.addShape(p.ShapeType.line, { x: x + w / 2, y: y + t, w: 0, h: t, line: { color, width: 1.75 } });
  s.addText(label, {
    x: x - 0.4, y: y + t + 0.16, w: w + 0.8, h: 0.5, align: "center",
    fontFace: BODY, fontSize: 11, bold: true, color, isTextBox: true, margin: 0, lineSpacingMultiple: 1.05,
  });
}

